func (v SpecValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	collectors := types.ListValueMust(
		CollectorsType{
			basetypes.ObjectType{
				AttrTypes: CollectorsValue{}.AttributeTypes(ctx),
			},
		},
		v.Collectors.Elements(),
	)

	if v.Collectors.IsNull() {
		collectors = types.ListNull(
			CollectorsType{
				basetypes.ObjectType{
					AttrTypes: CollectorsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.Collectors.IsUnknown() {
		collectors = types.ListUnknown(
			CollectorsType{
				basetypes.ObjectType{
					AttrTypes: CollectorsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	var interfaceSelectorsVal basetypes.ListValue
	switch {
	case v.InterfaceSelectors.IsUnknown():
		interfaceSelectorsVal = types.ListUnknown(types.StringType)
	case v.InterfaceSelectors.IsNull():
		interfaceSelectorsVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		interfaceSelectorsVal, d = types.ListValue(types.StringType, v.InterfaceSelectors.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"collectors": basetypes.ListType{
				ElemType: CollectorsValue{}.Type(ctx),
			},
			"dscp": basetypes.Int64Type{},
			"interface_selectors": basetypes.ListType{
				ElemType: types.StringType,
			},
			"interfaces": basetypes.ListType{
				ElemType: types.StringType,
			},
			"mode":              basetypes.StringType{},
			"rate":              basetypes.Int64Type{},
			"sample_size_bytes": basetypes.Int64Type{},
		}), diags
	}

	var interfacesVal basetypes.ListValue
	switch {
	case v.Interfaces.IsUnknown():
		interfacesVal = types.ListUnknown(types.StringType)
	case v.Interfaces.IsNull():
		interfacesVal = types.ListNull(types.StringType)
	default:
		var d diag.Diagnostics
		interfacesVal, d = types.ListValue(types.StringType, v.Interfaces.Elements())
		diags.Append(d...)
	}

	if diags.HasError() {
		return types.ObjectUnknown(map[string]attr.Type{
			"collectors": basetypes.ListType{
				ElemType: CollectorsValue{}.Type(ctx),
			},
			"dscp": basetypes.Int64Type{},
			"interface_selectors": basetypes.ListType{
				ElemType: types.StringType,
			},
			"interfaces": basetypes.ListType{
				ElemType: types.StringType,
			},
			"mode":              basetypes.StringType{},
			"rate":              basetypes.Int64Type{},
			"sample_size_bytes": basetypes.Int64Type{},
		}), diags
	}

	attributeTypes := map[string]attr.Type{
		"collectors": basetypes.ListType{
			ElemType: CollectorsValue{}.Type(ctx),
		},
		"dscp": basetypes.Int64Type{},
		"interface_selectors": basetypes.ListType{
			ElemType: types.StringType,
		},
		"interfaces": basetypes.ListType{
			ElemType: types.StringType,
		},
		"mode":              basetypes.StringType{},
		"rate":              basetypes.Int64Type{},
		"sample_size_bytes": basetypes.Int64Type{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"collectors":          collectors,
			"dscp":                v.Dscp,
			"interface_selectors": interfaceSelectorsVal,
			"interfaces":          interfacesVal,
			"mode":                v.Mode,
			"rate":                v.Rate,
			"sample_size_bytes":   v.SampleSizeBytes,
		})

	return objVal, diags
}

func (v SpecValue) Equal(o attr.Value) bool {
	other, ok := o.(SpecValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Collectors.Equal(other.Collectors) {
		return false
	}

	if !v.Dscp.Equal(other.Dscp) {
		return false
	}

	if !v.InterfaceSelectors.Equal(other.InterfaceSelectors) {
		return false
	}

	if !v.Interfaces.Equal(other.Interfaces) {
		return false
	}

	if !v.Mode.Equal(other.Mode) {
		return false
	}

	if !v.Rate.Equal(other.Rate) {
		return false
	}

	if !v.SampleSizeBytes.Equal(other.SampleSizeBytes) {
		return false
	}

	return true
}

